window.GL=(()=>{
const g=(s)=>s;
/* beaker: cx, bottom y, width, height, level 0-1, liquid colour */
const beaker=(cx,by,w,h,lv,col,o={})=>{ const x=cx-w/2, ly=by-h*lv; return `${LAB.C.shadow(cx,by+3,w*.62,5)}${lv>0?`<path d="M${x+3} ${ly}h${w-6}v${by-ly-6}a6 6 0 0 1-6 6h${-(w-18)}a6 6 0 0 1-6-6z" fill="${col}" opacity="${o.op||.8}"/>`:""}<path d="M${x-4} ${by-h}h4v${h-8}a8 8 0 0 0 8 8h${w-16}a8 8 0 0 0 8-8v${-(h-8)}h4" fill="url(#g-glass)" stroke="#6f8a96" stroke-width="1.6" stroke-opacity=".8"/>`; };
/* conical flask */
const flask=(cx,by,s,lv,col)=>{ const nw=s*.28, bw=s, h=s*1.15, neck=s*.32, ly=by-(h-neck)*lv*0.85; const half=y=>{ const t=(by-y)/(h-neck); return nw/2+(bw/2-nw/2)*(1-t); };
  return `${LAB.C.shadow(cx,by+3,bw*.6,5)}${lv>0?`<path d="M${cx-half(ly)} ${ly}L${cx-bw/2+4} ${by-4}h${bw-8}L${cx+half(ly)} ${ly}z" fill="${col}" opacity=".85"/>`:""}<path d="M${cx-nw/2} ${by-h}v${neck}L${cx-bw/2} ${by-3}q0 3 4 3h${bw-8}q4 0 4-3L${cx+nw/2} ${by-h+neck}v${-neck}" fill="url(#g-glass)" stroke="#6f8a96" stroke-width="1.6" stroke-opacity=".8"/>`; };
/* test tube: cx, top y, length, width, level, colour */
const tube=(cx,ty,len,w,lv,col,inv)=>{ const by=ty+len, ly=by-len*lv; return `${lv>0?(inv?`<path d="M${cx-w/2+2} ${ty}h${w-4}v${len*lv}h${-(w-4)}z" fill="${col}" opacity=".8"/>`:`<path d="M${cx-w/2+2} ${ly}h${w-4}v${by-ly-w/2}a${w/2-2} ${w/2-2} 0 0 1 ${-(w-4)} 0z" fill="${col}" opacity=".8"/>`):""}<path d="${inv?`M${cx-w/2} ${by}V${ty+w/2}a${w/2} ${w/2} 0 0 1 ${w} 0V${by}`:`M${cx-w/2} ${ty}V${by-w/2}a${w/2} ${w/2} 0 0 0 ${w} 0V${ty}`}" fill="url(#g-glass)" stroke="#6f8a96" stroke-width="1.4" stroke-opacity=".8"/>`; };
const bunsen=(cx,by,on,blue=true)=>`${LAB.C.shadow(cx,by+3,40,5)}<rect x="${cx-30}" y="${by-8}" width="60" height="8" rx="3" fill="url(#g-iron)"/><rect x="${cx-7}" y="${by-62}" width="14" height="56" fill="url(#g-steelV)"/>${on?`<path d="M${cx} ${by-64}c-14-20-6-40 0-58c6 18 14 38 0 58z" fill="${blue?"#4a8df0":"#f2a63a"}" opacity=".8"/><path d="M${cx} ${by-66}c-6-10-3-20 0-28c3 8 6 18 0 28z" fill="#bfe0ff" opacity=".9"/>`:""}`;
const tripod=(cx,ty,by,w=120)=>`<rect x="${cx-w/2-8}" y="${ty-4}" width="${w+16}" height="5" fill="#9aa0a6"/><path d="M${cx-w/2} ${ty}L${cx-w/2-12} ${by}M${cx+w/2} ${ty}L${cx+w/2+12} ${by}M${cx} ${ty}L${cx} ${by}" stroke="#4a5055" stroke-width="5"/>`;
const basin=(cx,by,w,lv,col,solid)=>`${LAB.C.shadow(cx,by+3,w*.55,4)}<path d="M${cx-w/2} ${by-w*.32}q${w/2} ${w*.6} ${w} 0z" fill="#ece8df" stroke="#bdb6a8"/>${lv>0?`<path d="M${cx-w/2+8} ${by-w*.3+4}q${w/2-8} ${w*.5} ${w-16} 0z" fill="${col}" opacity=".85"/>`:""}${solid?`<path d="M${cx-w/4} ${by-w*.12}q${w/4} ${w*.12} ${w/2} 0z" fill="${solid}"/>`:""}`;
/* burette with liquid; reading r (cm3) from top scale 0..50 */
const burette=(x,ty,len,r,col,id)=>{ const s0=ty+20, s1=ty+len-30, k=(s1-s0)/50, ly=s0+r*k; let t=""; for(let v=0;v<=50;v++){ const y=s0+v*k, L=v%5===0?10:5; t+=`<line x1="${x-7}" x2="${x-7+L}" y1="${y.toFixed(1)}" y2="${y.toFixed(1)}" stroke="#334" stroke-width="${v%5?0.5:0.9}" opacity=".8"/>`; if(v%10===0) t+=`<text x="${x+10}" y="${(y+3).toFixed(1)}" font-size="8" font-family="Arial" fill="#1d2a33">${v}</text>`; }
  return `<rect x="${x-7}" y="${ly.toFixed(1)}" width="14" height="${(s1+20-ly).toFixed(1)}" fill="${col}" opacity=".55" id="${id||""}"/><rect x="${x-8}" y="${ty}" width="16" height="${len-10}" rx="3" fill="url(#g-glass)" stroke="#6f8a96" stroke-opacity=".8"/>${t}<rect x="${x-14}" y="${ty+len-12}" width="28" height="8" rx="2" fill="#2b6a3c"/><path d="M${x} ${ty+len-4}v14" stroke="#6f8a96" stroke-width="3"/>`; };
return {beaker,flask,tube,bunsen,tripod,basin,burette};
})();


/* RP8 Making salts */
(()=>{
const {$,C,W,fx,gauss,bars,rows,build,register}=LAB;
const MR=249.5, NA=0.025, NEED=5;
const st={step:0,n:0,warm:false,dry:false,data:[]};
const stage=`<svg id="salt-svg" viewBox="0 0 900 470" role="img" aria-label="Making copper(II) sulfate crystals">${C.room()}<g id="salt-g"></g></svg>`;
const panel=`<div class="btnrow" style="flex-wrap:wrap"><button class="btn" id="salt-warm">Warm the acid</button><button class="btn" id="salt-add">Add a spatula of CuO</button><button class="btn" id="salt-fil">Filter</button><button class="btn" id="salt-ev">Heat to evaporate</button><button class="btn" id="salt-cr">Leave to crystallise</button><button class="btn primary" id="salt-wt">Dry and weigh crystals</button><button class="btn" id="salt-new">Start a new attempt</button></div>
<div class="readout"><div><span>Stage</span><b id="salt-s">—</b></div><div><span>CuO added</span><b id="salt-n">0</b></div></div><p class="note" id="salt-h"></p>`;
build({id:"salt",eyebrow:"AQA GCSE Combined Science · Chemistry · Required practical 8 · Chemical changes",title:"Making a soluble salt",
 intro:"Prepare a pure, dry sample of copper(II) sulfate crystals from copper(II) oxide and dilute sulfuric acid, then calculate your percentage yield.",
 stage,bar:`<span>25.0 cm³ of 1.0 mol/dm³ H₂SO₄</span><span>1 spatula ≈ 0.40 g CuO</span>`,panel,
 results:`<div class="tbl-wrap"><table><thead><tr><th>Attempt</th><th>CuO added / g</th><th>Crystals / g</th><th>Yield / %</th><th>Notes</th><th></th></tr></thead><tbody id="salt-tbody"></tbody></table></div>`,
 graphTitle:"Percentage yield of each attempt",graphSub:"Theoretical maximum: 6.24 g",
 info:{method:["Measure 25 cm³ of dilute sulfuric acid into a beaker and warm it gently on a tripod and gauze (do not boil).","Add copper(II) oxide a spatula at a time, stirring, until some remains undissolved: the base is in excess, so all the acid has reacted.","Filter the warm mixture to remove the excess copper(II) oxide. Collect the blue filtrate in an evaporating basin.","Heat the filtrate over a water bath or gently until about half the water has evaporated and crystals start to form at the edge.","Leave to cool and crystallise. Filter off the crystals and dry them between filter papers.","Weigh the crystals and calculate the percentage yield."],
 vars:["(Preparation, not an investigation)","Mass of crystals obtained","Volume and concentration of acid; method of crystallisation"],
 safety:["Wear eye protection: sulfuric acid and copper(II) sulfate are irritants.","Do not boil the acid; heat gently to avoid spitting.","Copper(II) oxide powder is harmful: avoid raising dust."],
 qa:[["Why is copper(II) oxide added until some is left over?","So that all the sulfuric acid reacts. Excess base can be filtered off; excess acid could not be removed and would contaminate the crystals."],["Why is the acid warmed?","To increase the rate of reaction so the oxide dissolves faster."],["Why is the filtrate not heated to dryness?","Heating to dryness removes the water of crystallisation, giving white anhydrous powder instead of blue crystals, and can decompose the salt."],["Calculate the theoretical maximum mass of CuSO₄·5H₂O from 25.0 cm³ of 1.0 mol/dm³ H₂SO₄.","0.0250 mol H₂SO₄ → 0.0250 mol CuSO₄·5H₂O; 0.0250 × 249.5 = 6.24 g."],["Give two reasons why the yield is less than 100%.","Some solution remains in the filter paper and apparatus; some copper sulfate stays dissolved in the remaining solution; some crystals are lost on transfer."]]}});
function draw(){ const d=st.step; let s="";
  if(d<=1){ const blue=Math.min(st.n,NEED)/NEED; s+=GL.tripod(420,300,400,150)+GL.bunsen(420,400,st.warm)+GL.beaker(420,296,130,140,.42,`rgb(${Math.round(160-130*blue)},${Math.round(200-80*blue)},${Math.round(225)})`);
    for(let i=0;i<Math.max(0,st.n-NEED)*8;i++) s+=`<circle cx="${370+(i*23)%100}" cy="${290-(i%3)*3}" r="3" fill="#151515"/>`;
    s+=`<text x="600" y="200" font-family="Arial" font-size="15" fill="#1d2a33">${st.n>NEED?"black solid remains: excess":"copper(II) oxide dissolving"}</text>`; }
  else if(d===2){ s+=`<path d="M380 120h100l-40 50v40h-20v-40z" fill="url(#g-glass)" stroke="#6f8a96"/><path d="M398 128c14 6 34 6 46 0" stroke="#151515" stroke-width="6"/>`+GL.basin(430,380,170,1,"#3f7fd0")+`<path d="M430 210v130" stroke="#3f7fd0" stroke-width="3" stroke-dasharray="3 6"/><text x="520" y="140" font-family="Arial" font-size="14" fill="#1d2a33">residue: excess CuO</text><text x="530" y="360" font-family="Arial" font-size="14" fill="#1d2a33">filtrate: copper(II) sulfate solution</text>`; }
  else if(d===3){ s+=GL.tripod(430,300,400,150)+GL.bunsen(430,400,true)+GL.basin(430,298,170,st.dry?0:.7,"#2a63c4",st.dry?"#f4f4f0":null)+`<text x="560" y="220" font-family="Arial" font-size="14" fill="#1d2a33">${st.dry?"heated to dryness: white powder!":"evaporating: crystals start at the edge"}</text>`; }
  else { s+=GL.basin(430,380,190,st.dry?0:.4,"#5b9be0",st.dry?"#f4f4f0":null); if(!st.dry) [[380,355],[410,362],[445,358],[475,352],[425,346]].forEach(([x,y])=>s+=`<path d="M${x} ${y-10}l10 6v12l-10 6l-10-6v-12z" fill="#1e63c6" stroke="#bcd8ff"/>`); s+=`<text x="560" y="330" font-family="Arial" font-size="14" fill="#1d2a33">${st.dry?"anhydrous powder":"blue crystals"}</text>`; }
  $("#salt-g").innerHTML=s; $("#salt-s").textContent=["Reacting","Reacting","Filtered","Evaporating","Crystallised"][d]; $("#salt-n").textContent=`${st.n} spatulas (${fx(st.n*.4,1)} g)`; }
function hint(t){ $("#salt-h").textContent=t; }
$("#salt-warm").onclick=()=>{ if(st.step>1) return; st.warm=!st.warm; hint(st.warm?"Warming the acid speeds up the reaction.":"Bunsen off."); draw(); };
$("#salt-add").onclick=()=>{ if(st.step>1) return; if(!st.warm&&st.n>=2) hint("The oxide is dissolving slowly. Warming the acid would speed this up."); st.n++; st.step=1; draw(); };
$("#salt-fil").onclick=()=>{ if(st.step!==1) return; if(st.n<=NEED) hint("Warning: no excess solid yet, so some acid has not reacted. Your crystals will be contaminated."); else hint("Excess CuO removed. Now heat the filtrate."); st.excess=st.n>NEED; st.step=2; draw(); };
$("#salt-ev").onclick=()=>{ if(st.step===2){ st.step=3; hint("Heat until crystals start to form, then stop. Pressing again heats to dryness."); } else if(st.step===3){ st.dry=true; hint("You have heated it to dryness: the water of crystallisation has been driven off."); } draw(); };
$("#salt-cr").onclick=()=>{ if(st.step===3){ st.step=4; hint("Crystals have formed. Dry and weigh them."); draw(); } };
$("#salt-wt").onclick=()=>{ if(st.step!==4) return; const used=Math.min(st.n,NEED)/NEED; let y=(0.72+0.08*Math.random())*used; let note="good blue crystals"; if(!st.excess){ y*=.85; note="acid left: sticky, impure crystals"; } if(st.dry){ y*=160/249.5; note="white anhydrous powder (water lost)"; }
  const m=+(NA*MR*y).toFixed(2); st.data.push({cu:+(st.n*.4).toFixed(1),m,pc:m/(NA*MR)*100,note}); refresh(); hint("Recorded. Start a new attempt to compare."); };
$("#salt-new").onclick=()=>{ Object.assign(st,{step:0,n:0,warm:false,dry:false,excess:false}); hint("Measure 25 cm³ of acid into the beaker, then warm it."); draw(); };
$("#salt-tbody").addEventListener("click",e=>{ const b=e.target.closest(".x"); if(!b) return; st.data.splice(+b.dataset.i,1); refresh(); });
function refresh(){ rows($("#salt-tbody"),st.data.map((r,i)=>[i+1,fx(r.cu,1),fx(r.m,2),fx(r.pc,0),r.note]),"Make some crystals to record a result.",5,true); graph(); work(); }
function graph(){ bars($("#salt-graph"),{ylabel:"Yield / %",items:st.data.map((r,i)=>({label:`Attempt ${i+1}`,v:r.pc,vl:fx(r.pc,0)+"%"})),empty:"Yields will appear here"}); }
function work(){ const el=$("#salt-work"), {fr,res,step,chips}=W; if(!st.data.length){ el.innerHTML=`<p class="empty">Weigh some crystals and the calculation will appear here.</p>`; return; } const r=st.data[st.data.length-1];
  el.innerHTML=chips([["Theoretical yield","6.24 g",1],["Your crystals",`${fx(r.m,2)} g`],["Percentage yield",`${fx(r.pc,0)}%`]])+`<div class="work" style="margin-top:14px">`+step(1,"Moles of acid","moles = concentration × volume",[`0.0250 dm³ × 1.0 mol/dm³ = 0.0250 mol H₂SO₄`])+step(2,"Maximum mass of crystals","CuO + H₂SO₄ → CuSO₄ + H₂O, then 1 CuSO₄ crystallises with 5 H₂O",[`M<sub>r</sub> CuSO₄·5H₂O = 63.5 + 32 + 64 + 5 × 18 = 249.5`,`0.0250 × 249.5 = ${res("6.24 g")}`])+step(3,"Percentage yield",null,[`${fr(fx(r.m,2),"6.24")} × 100 = ${res(fx(r.pc,0)+"%")}`])+`</div>`; }
hint("Measure 25 cm³ of acid into the beaker, then warm it."); draw(); refresh();
register({id:"salt",group:"rp-chem",num:8,lvl:"RP 8",name:"Making salts",icon:"rp-salt",onShow:()=>{draw();graph();}});
})();


/* RP9 Electrolysis */
(()=>{
const {$,C,W,fx,plot,rows,build,register,RUNCOL}=LAB;
const S=[{n:"copper(II) chloride",liq:"#5fb3a8",cat:["copper","solid",0,"pink-brown coating"],an:["chlorine","gas",0.35,"bleaches damp litmus"],why:"Copper is less reactive than hydrogen; chloride is a halide."},
 {n:"sodium chloride",liq:"#9cc8e8",cat:["hydrogen","gas",1,"squeaky pop"],an:["chlorine","gas",0.4,"bleaches damp litmus"],why:"Sodium is more reactive than hydrogen; chloride is a halide. (Chlorine is quite soluble, so less is collected.)"},
 {n:"copper(II) sulfate",liq:"#5b9be0",cat:["copper","solid",0,"pink-brown coating"],an:["oxygen","gas",0.5,"relights a glowing splint"],why:"Copper is less reactive than hydrogen; no halide, so oxygen from hydroxide ions."},
 {n:"potassium bromide",liq:"#9cc8e8",cat:["hydrogen","gas",1,"squeaky pop"],an:["bromine","sol",0,"orange-brown colour around the anode"],why:"Potassium is more reactive than hydrogen; bromide is a halide (bromine dissolves)."},
 {n:"sodium sulfate",liq:"#9cc8e8",cat:["hydrogen","gas",1,"squeaky pop"],an:["oxygen","gas",0.5,"relights a glowing splint"],why:"Sodium is more reactive than hydrogen; no halide, so oxygen."}];
const st={k:0,on:false,t:0,last:0,data:[],trace:[]};
const stage=`<svg id="elec-svg" viewBox="0 0 900 470" role="img" aria-label="Electrolysis cell with gas collecting tubes">${C.room()}${C.psu(640,250,"elec-psu",{max:12})}<g id="elec-g"></g>${C.stopwatch(40,180,"elec-sw")}</svg>`;
const panel=`<div class="field"><div class="lbl">Solution</div><select id="elec-s">${S.map((s,i)=>`<option value="${i}">${s.n}</option>`).join("")}</select></div>
<div class="btnrow"><button class="btn primary" id="elec-on">Switch on</button><button class="btn" id="elec-reset">Empty and refill</button></div>
<div class="readout"><div><span>Cathode (−)</span><b id="elec-c">—</b></div><div><span>Anode (+)</span><b id="elec-a">—</b></div></div>
<div class="btnrow"><button class="btn" id="elec-tc">Test cathode product</button><button class="btn" id="elec-ta">Test anode product</button></div><p class="note" id="elec-h">Choose a solution and switch on the power supply.</p>`;
build({id:"elec",eyebrow:"AQA GCSE Combined Science · Chemistry · Required practical 9 · Chemical changes",title:"Electrolysis of aqueous solutions",
 intro:"Electrolyse aqueous solutions with inert carbon electrodes, collect any gases and test them to identify the products at each electrode.",
 stage,bar:`<span>Inert carbon electrodes</span><span>6 V d.c.</span>`,panel,
 results:`<div class="tbl-wrap"><table><thead><tr><th>Solution</th><th>Cathode observation</th><th>Anode observation</th><th></th></tr></thead><tbody id="elec-tbody"></tbody></table></div>`,
 graphTitle:"Gas collected against time",graphSub:"Current run",workTitle:"Explaining the products",workSub:"Uses your results",
 info:{method:["Pour the solution into a beaker or electrolysis cell. Fill two small test tubes with the solution and invert them over the carbon electrodes.","Connect the electrodes to a low-voltage d.c. supply (about 6 V) and switch on.","Observe each electrode. Collect any gas until a tube is about half full, then switch off.","Test the gases: hydrogen (burning splint: squeaky pop), oxygen (glowing splint relights), chlorine (bleaches damp blue litmus paper).","Repeat with other solutions and record your observations."],
 vars:["The solution electrolysed","The products at each electrode","Voltage, electrode material, concentration, time"],
 safety:["Wear eye protection.","Chlorine is toxic: use a well-ventilated room, run for short times only, and do not smell the gas.","Copper(II) salts are harmful; wash hands after use. Keep the voltage low."],
 qa:[["Why are inert electrodes used?","So they do not react with the products or the electrolyte; only the ions in solution are discharged."],["Why is hydrogen produced at the cathode in sodium chloride solution?","Sodium is more reactive than hydrogen, so hydrogen ions from water are discharged instead."],["Why is less chlorine collected than hydrogen from sodium chloride solution?","Chlorine is fairly soluble in water, so some dissolves."],["What is the volume ratio of hydrogen to oxygen from sodium sulfate solution, and why?","2 : 1, because 4 electrons give 2 H₂ at the cathode but only 1 O₂ at the anode."],["Write the half equation for the cathode in copper(II) sulfate solution.","Cu²⁺ + 2e⁻ → Cu"]]}});
function draw(){ const s=S[st.k], tt=Math.min(st.t,180); let g=GL.beaker(400,410,260,170,.82,s.liq);
  const vol=(p)=>p[1]==="gas"?Math.min(1,tt*p[2]/120):0;
  [[340,s.cat],[460,s.an]].forEach(([x,p],i)=>{ g+=`<rect x="${x-7}" y="230" width="14" height="150" fill="#2b2b2b"/>`;
    if(p[1]==="solid") g+=`<rect x="${x-10}" y="${380-Math.min(1,tt/60)*110}" width="20" height="${Math.min(1,tt/60)*110}" fill="#c87533" opacity="${Math.min(1,tt/40)}"/>`;
    if(p[1]==="sol"&&tt>0) g+=`<ellipse cx="${x}" cy="330" rx="${20+Math.min(30,tt/4)}" ry="60" fill="#d9792b" opacity="${Math.min(.6,tt/100)}"/>`;
    g+=GL.tube(x,220,140,34,0,"",true); const v=vol(p); if(v>0) g+=`<rect x="${x-15}" y="${222}" width="30" height="${138*v}" fill="#eef6fb" opacity=".5"/>`;
    if(st.on&&p[1]==="gas") for(let b=0;b<4;b++) g+=`<circle cx="${x+((b*7+st.t*30)%14)-7}" cy="${380-((st.t*80+b*30)%140)}" r="2.5" fill="none" stroke="#fff"/>`;
    g+=`<text x="${x}" y="440" text-anchor="middle" font-family="Arial" font-size="13" fill="#1d2a33">${i?"anode (+)":"cathode (−)"}</text>`; });
  g+=`<path d="M340 230V160H640M460 230V180H660" fill="none" stroke="${st.on?"#d33":"#777"}" stroke-width="3"/>`;
  $("#elec-g").innerHTML=g; LAB.setStopwatch($("#elec-sw"),st.t); LAB.setPsu("elec-psu",6,12,st.on); }
function graph(){ const s=S[st.k], pts=[0,1].map(i=>st.trace.map(([t,a,b])=>[t,i?b:a])); plot($("#elec-graph"),{x:{label:"Time / s",def:[0,180]},y:{label:"Volume of gas / cm³",def:[0,10]},series:[{pts:pts[0],col:RUNCOL[1],join:"line",noPts:true,label:"cathode: "+s.cat[0]},{pts:pts[1],col:RUNCOL[0],join:"line",noPts:true,label:"anode: "+s.an[0]}],empty:"Switch on to collect gas"}); }
LAB.C&&CH.loop("elec",dt=>{ if(!st.on) return; st.t+=dt*4; const s=S[st.k], tt=Math.min(st.t,180), v=p=>p[1]==="gas"?Math.min(1,tt*p[2]/120)*9:0; if(st.t-st.last>=5){ st.last=st.t; st.trace.push([+st.t.toFixed(0),v(s.cat),v(s.an)]); graph(); }
  $("#elec-c").textContent=s.cat[1]==="gas"?`gas: ${fx(v(s.cat),1)} cm³`:s.cat[3]; $("#elec-a").textContent=s.an[1]==="gas"?`gas: ${fx(v(s.an),1)} cm³`:s.an[3]; if(st.t>=180){ st.on=false; $("#elec-on").textContent="Switch on"; } draw(); });
const tests={hydrogen:"Burning splint: squeaky pop. The gas is hydrogen.",oxygen:"Glowing splint relights. The gas is oxygen.",chlorine:"Damp blue litmus turns red then white (bleached). The gas is chlorine.",copper:"A pink-brown solid has coated the electrode: copper.",bromine:"The solution around the electrode has turned orange-brown: bromine."};
function test(i){ const s=S[st.k], p=i?s.an:s.cat; if(st.t<20){ $("#elec-h").textContent="Run the electrolysis for longer first."; return; } $("#elec-h").textContent=tests[p[0]];
  let row=st.data.find(r=>r.k===st.k&&r.run===st.run); if(!row){ row={k:st.k,run:st.run,c:"—",a:"—"}; st.data.push(row); } if(i) row.a=`${p[3]}: ${p[0]}`; else row.c=`${p[3]}: ${p[0]}`; refresh(); }
$("#elec-tc").onclick=()=>test(0); $("#elec-ta").onclick=()=>test(1);
$("#elec-on").onclick=()=>{ st.on=!st.on; $("#elec-on").textContent=st.on?"Switch off":"Switch on"; draw(); };
function reset(){ st.on=false; st.t=0; st.last=0; st.trace=[[0,0,0]]; st.run=(st.run||0)+1; $("#elec-on").textContent="Switch on"; $("#elec-c").textContent="—"; $("#elec-a").textContent="—"; draw(); graph(); }
$("#elec-reset").onclick=reset; $("#elec-s").onchange=()=>{ st.k=+$("#elec-s").value; reset(); };
$("#elec-tbody").addEventListener("click",e=>{ const b=e.target.closest(".x"); if(!b) return; st.data.splice(+b.dataset.i,1); refresh(); });
function refresh(){ rows($("#elec-tbody"),st.data.map(r=>[S[r.k].n,r.c,r.a]),"Test the products to record them.",3,true); work(); }
function work(){ const el=$("#elec-work"); if(!st.data.length){ el.innerHTML=`<p class="empty">Test the products and an explanation will appear here.</p>`; return; } el.innerHTML=`<div class="work">`+[...new Set(st.data.map(r=>r.k))].map((k,i)=>W.step(i+1,S[k].n,null,[`<span>Cathode: ${S[k].cat[0]}. Anode: ${S[k].an[0]}. ${S[k].why}</span>`])).join("")+`</div>`; }
reset(); refresh();
register({id:"elec",group:"rp-chem",num:9,lvl:"RP 9",name:"Electrolysis",icon:"rp-elec",onShow:()=>{draw();graph();}});
})();


/* RP10 Temperature changes */
(()=>{
const {$,C,W,fx,gauss,plot,rows,build,register,linfit,RUNCOL}=LAB;
const st={c:+(1.4+Math.random()*0.5).toFixed(2),V:0,T0:+(19+Math.random()*3).toFixed(1),data:[],shown:0};
const Tof=V=>{ const na=0.025*st.c, nb=0.002*V, n=Math.min(na,nb); return st.T0+n*57100/(4.18*(25+V))*0.93; };
const stage=`<svg id="temp-svg" viewBox="0 0 900 470" role="img" aria-label="Polystyrene cup with thermometer">${C.room()}${C.thermo(450,40,300,"temp-th",{tMin:0,tMax:50})}<g id="temp-g"></g>${C.mag(720,170,90,"temp-mag")}</svg>`;
const panel=`<div class="readout"><div><span>Total NaOH added</span><b id="temp-v">0 cm³</b></div><div><span>Thermometer</span><b id="temp-t">—</b></div></div>
<div class="btnrow"><button class="btn" id="temp-add">Add 5.0 cm³ NaOH and stir</button><button class="btn primary" id="temp-rec">Record highest temperature</button></div><div class="btnrow"><button class="btn" id="temp-new">Start again with fresh acid</button></div><p class="note">Sodium hydroxide: 2.0 mol/dm³. Read the highest temperature after each addition.</p>`;
build({id:"temp",eyebrow:"AQA GCSE Combined Science · Chemistry · Required practical 10 · Energy changes",title:"Temperature changes in neutralisation",
 intro:"Add sodium hydroxide solution in 5 cm³ portions to 25 cm³ of hydrochloric acid in a polystyrene cup and record the highest temperature each time. Use the graph to find the volume needed for neutralisation.",
 stage,bar:`<span>25.0 cm³ HCl in a polystyrene cup with a lid</span><span>Thermometer resolution 0.5 °C</span>`,panel,
 results:`<div class="tbl-wrap"><table><thead><tr><th>Total volume of NaOH / cm³</th><th>Highest temperature / °C</th><th></th></tr></thead><tbody id="temp-tbody"></tbody></table></div>`,
 graphTitle:"Highest temperature against volume added",graphSub:"Lines of best fit cross at the neutral point",
 info:{method:["Measure 25 cm³ of dilute hydrochloric acid into a polystyrene cup standing in a beaker. Record the temperature.","Add 5 cm³ of sodium hydroxide solution, stir with the thermometer, and record the highest temperature reached.","Continue adding 5 cm³ portions, recording the highest temperature each time, up to 40 cm³.","Repeat the experiment and calculate mean temperatures.","Plot highest temperature against volume of NaOH. Draw two straight lines of best fit; where they cross is the volume needed to neutralise the acid."],
 vars:["Volume of sodium hydroxide added","Highest temperature","Volume and concentration of acid, concentration of alkali, type of cup, starting temperature"],
 safety:["Wear eye protection: acid and alkali are irritants.","Stand the cup in a beaker so it cannot tip over.","Mop up spills immediately."],
 qa:[["Why does the temperature rise at first?","Neutralisation is exothermic; more acid reacts as more alkali is added, releasing more energy."],["Why does the temperature fall after the maximum?","All the acid has reacted. The extra alkali is cooler and absorbs energy from the mixture."],["Why is a lid used?","To reduce energy transfer to the surroundings by evaporation and convection."],["How can the volume at the peak be used to find the acid concentration?","At the end point moles NaOH = moles HCl, so c(HCl) = 2.0 × V ÷ 25."],["Suggest one improvement.","Use smaller additions near the peak; use a thermometer or temperature probe with higher resolution; repeat and take means."]]}});
function draw(){ const T=st.shown; LAB.setThermo("temp-th",T); const lv=(25+st.V)/80; $("#temp-g").innerHTML=`<path d="M380 250l16 150h108l16-150z" fill="#f3f3ee" stroke="#ccc"/><rect x="372" y="238" width="156" height="14" rx="4" fill="#e6e6e0"/><path d="M${398-6*lv} ${400-150*lv}h${104+12*lv}l${-8*lv} ${150*lv-2}h${-88}z" fill="#9cc8e8" opacity=".55"/>`;
  $("#temp-mag").innerHTML=`<rect x="630" y="80" width="180" height="180" fill="#f7f5ec"/>`+(()=>{ let m=""; const y0=170+(T-Math.round(T))*40; for(let k=-3;k<=3;k++){ const t=Math.round(T)+k, y=170-(t-T)*40; m+=`<line x1="700" x2="${t%5===0?740:725}" y1="${y}" y2="${y}" stroke="#222" stroke-width="2"/>`; if(t%5===0) m+=`<text x="748" y="${y+6}" font-family="Arial" font-size="16" fill="#222">${t}</text>`; } return m+`<rect x="686" y="170" width="8" height="120" fill="#d42a22"/>`; })();
  $("#temp-v").textContent=`${st.V} cm³`; $("#temp-t").textContent=`${fx(Math.round(T*2)/2,1)} °C`; }
let anim=null; function rise(){ const target=Tof(st.V); const from=st.shown; const t0=performance.now(); cancelAnimationFrame(anim); const step=now=>{ const u=Math.min(1,(now-t0)/1200); st.shown=from+(target-from)*(1-Math.pow(1-u,3)); draw(); if(u<1) anim=requestAnimationFrame(step); }; anim=requestAnimationFrame(step); }
$("#temp-add").onclick=()=>{ if(st.V>=40) return; st.V+=5; rise(); };
$("#temp-rec").onclick=()=>{ const T=Math.round((Tof(st.V)+gauss()*.15)*2)/2; const i=st.data.findIndex(r=>r.V===st.V); if(i>=0) st.data[i].T=T; else st.data.push({V:st.V,T}); st.data.sort((a,b)=>a.V-b.V); refresh(); };
$("#temp-new").onclick=()=>{ st.V=0; st.shown=st.T0; st.data=[]; draw(); refresh(); };
$("#temp-tbody").addEventListener("click",e=>{ const b=e.target.closest(".x"); if(!b) return; st.data.splice(+b.dataset.i,1); refresh(); });
function analyse(){ const d=st.data; if(d.length<5) return null; const pk=d.reduce((a,b)=>b.T>a.T?b:a); const up=d.filter(r=>r.V<=pk.V&&r.V<pk.V+.1).filter(r=>r.V<pk.V||true), A=d.filter(r=>r.V<pk.V), B=d.filter(r=>r.V>pk.V); if(A.length<2||B.length<2) return null; const f1=linfit(A.map(r=>[r.V,r.T])), f2=linfit(B.map(r=>[r.V,r.T])); const x=(f2.c-f1.c)/(f1.m-f2.m); return {f1,f2,x,y:f1.m*x+f1.c}; }
function graph(){ const a=analyse(); const o={x:{label:"Volume of NaOH added / cm³",def:[0,40]},y:{label:"Highest temperature / °C",def:[15,35],zero:false},series:[{pts:st.data.map(r=>[r.V,r.T]),col:RUNCOL[0]}],empty:"Record the highest temperature after each addition"};
  if(a){ o.fits=[{m:a.f1.m,c:a.f1.c,x0:0,x1:a.x+2},{m:a.f2.m,c:a.f2.c,x0:a.x-2,x1:40}]; } plot($("#temp-graph"),o); }
function refresh(){ rows($("#temp-tbody"),st.data.map(r=>[r.V,fx(r.T,1)]),"Record the starting temperature with 0 cm³ added first.",2,true); graph(); work(); }
function work(){ const el=$("#temp-work"), {fr,res,step,chips}=W, a=analyse(); if(!a){ el.innerHTML=`<p class="empty">Record at least two points before and two after the peak.</p>`; return; } const c=2.0*a.x/25, t0=(st.data.find(r=>r.V===0)||{T:st.T0}).T;
  el.innerHTML=chips([["Neutral point",`${fx(a.x,1)} cm³`,1],["Maximum rise",`${fx(a.y-t0,1)} °C`],["HCl concentration",`${fx(c,2)} mol/dm³`]])+`<div class="work" style="margin-top:14px">`+step(1,"Where the lines cross","Two lines of best fit meet at the neutral point.",[`V ≈ ${fx(a.x,1)} cm³ ; highest temperature ≈ ${fx(a.y,1)} °C`])+step(2,"Moles of NaOH at the neutral point",null,[`2.0 × ${fr(fx(a.x,1),"1000")} = ${fx(2*a.x/1000,4)} mol`])+step(3,"Concentration of HCl","HCl + NaOH → NaCl + H₂O: 1 : 1",[`${fr(fx(2*a.x/1000,4),"0.0250")} = ${res(fx(c,2)+" mol/dm³")}`])+`</div>`; }
st.shown=st.T0; draw(); refresh();
register({id:"temp",group:"rp-chem",num:10,lvl:"RP 10",name:"Temperature changes",icon:"rp-temp",onShow:()=>{draw();graph();}});
})();


/* RP11 Rates of reaction */
(()=>{
const {$,C,W,fx,gauss,plot,rows,build,register,RUNCOL}=LAB;
const VF=96;
const st={c:1.0,run:false,t:0,pts:[],runs:[]};
const k=c=>0.04*c;
const stage=`<svg id="rate-svg" viewBox="0 0 900 470" role="img" aria-label="Conical flask connected to a gas syringe">${C.room()}<g id="rate-g"></g>${C.stopwatch(60,190,"rate-sw")}</svg>`;
const panel=`<div class="field"><div class="lbl">Concentration of hydrochloric acid</div><div class="seg c2" id="rate-c">${[0.5,1.0,1.5,2.0].map(v=>`<label class="opt"><input type="radio" name="rate-c" value="${v}" ${v===1?"checked":""}><span>${v.toFixed(1)} mol/dm³</span></label>`).join("")}</div></div>
<div class="btnrow"><button class="btn primary" id="rate-go">Add the magnesium and start</button><button class="btn" id="rate-clear">Clear all runs</button></div>
<div class="readout"><div><span>Time</span><b id="rate-tt">0 s</b></div><div><span>Gas syringe</span><b id="rate-v">0 cm³</b></div></div><p class="note">Readings are recorded automatically every 10 s for 120 s. 0.10 g magnesium ribbon, 50 cm³ acid (acid in excess).</p>`;
build({id:"rate",eyebrow:"AQA GCSE Combined Science · Chemistry · Required practical 11 · Rates of reaction",title:"Rate of reaction and concentration",
 intro:"Measure the volume of hydrogen produced when magnesium ribbon reacts with hydrochloric acid of different concentrations, and compare the rates.",
 stage,bar:`<span>Gas syringe 0–100 cm³</span><span>Mg + 2HCl → MgCl₂ + H₂</span>`,panel,
 results:`<div class="tbl-wrap"><table><thead><tr><th>Concentration / mol/dm³</th><th>Volume at 10 s / cm³</th><th>Volume at 30 s / cm³</th><th>Final volume / cm³</th><th>Mean rate in first 30 s / cm³/s</th><th></th></tr></thead><tbody id="rate-tbody"></tbody></table></div>`,
 graphTitle:"Volume of hydrogen against time",graphSub:"One line per concentration",
 info:{method:["Measure 50 cm³ of hydrochloric acid into a conical flask.","Connect a bung and delivery tube to a gas syringe (or an upturned measuring cylinder in a trough of water).","Add a 0.10 g piece of magnesium ribbon, replace the bung quickly and start the stopwatch.","Record the volume of gas every 10 s until the reaction stops.","Repeat with different concentrations of acid. Plot volume against time for each.","Second method (turbidity): time how long it takes for a cross under a flask of sodium thiosulfate and hydrochloric acid to disappear, for different concentrations of thiosulfate."],
 vars:["Concentration of hydrochloric acid","Volume of gas produced over time (or time for the cross to disappear)","Mass and length of magnesium ribbon, volume of acid, temperature"],
 safety:["Wear eye protection.","Hydrogen is flammable: no naked flames nearby.","In the thiosulfate method, sulfur dioxide is produced: ventilate the room and avoid inhaling; people with asthma should take care."],
 qa:[["Why does the reaction get slower as time goes on?","The magnesium is used up, so there are fewer particles to collide and the frequency of successful collisions falls."],["Why is the final volume the same for each concentration?","The magnesium is the limiting reactant and the same mass is used each time."],["Explain why a higher concentration gives a faster rate.","More acid particles in the same volume, so more frequent collisions with the magnesium."],["How could the initial rate be found more accurately?","Draw a tangent to the curve at t = 0 and find its gradient."],["Give one source of error with a gas syringe.","Gas escapes before the bung is replaced; the syringe plunger may stick."]]}});
function draw(){ const V=st.pts.length?st.pts[st.pts.length-1][1]:0; let g=GL.flask(260,410,130,.3,"#cfe6f5")+`<rect x="245" y="245" width="30" height="16" rx="3" fill="#8a5a3a"/><path d="M260 245V200H420" fill="none" stroke="#6f8a96" stroke-width="5"/><text x="600" y="168" text-anchor="middle" font-family="Arial" font-size="13" fill="#1d2a33">gas syringe / cm³</text>`;
  if(st.run&&st.t<110) for(let i=0;i<6;i++) g+=`<circle cx="${250+(i*7)%20}" cy="${400-((st.t*60+i*20)%40)}" r="2.5" fill="none" stroke="#fff"/>`;
  g+=`<rect x="${255}" y="${396}" width="${Math.max(0,20*(1-V/VF))}" height="4" fill="#c0c4c8"/>`;
  const sx=420, sw=300; g+=`<rect x="${sx}" y="180" width="${sw}" height="40" rx="6" fill="url(#g-glass)" stroke="#6f8a96" stroke-opacity=".8"/>`; for(let v=0;v<=100;v+=10) g+=`<line x1="${sx+v/100*sw}" x2="${sx+v/100*sw}" y1="180" y2="${v%50?190:196}" stroke="#334" stroke-width="1"/><text x="${sx+v/100*sw}" y="236" text-anchor="middle" font-family="Arial" font-size="10" fill="#1d2a33">${v}</text>`;
  const px=sx+V/100*sw; g+=`<rect x="${px}" y="186" width="6" height="28" fill="#555"/><rect x="${px}" y="198" width="${sw-(px-sx)+40}" height="4" fill="#888"/><rect x="${sx+sw+40}" y="186" width="8" height="28" fill="#555"/>`;
  $("#rate-g").innerHTML=g; LAB.setStopwatch($("#rate-sw"),st.t); $("#rate-tt").textContent=`${Math.floor(st.t)} s`; $("#rate-v").textContent=`${fx(V,0)} cm³`; }
CH.loop("rate",dt=>{ if(!st.run) return; st.t+=dt*3; const V=VF*(1-Math.exp(-k(st.c)*st.t)); const tt=Math.floor(st.t/10)*10; if(!st.pts.length||tt>st.pts[st.pts.length-1][0]){ st.pts.push([tt,Math.round((VF*(1-Math.exp(-k(st.c)*tt))+gauss()*.6)*1)]); graph(); }
  if(st.t>=120){ st.run=false; st.runs.push({c:st.c,pts:st.pts.slice()}); refresh(); } draw(); });
$("#rate-go").onclick=()=>{ if(st.run) return; st.c=+document.querySelector("input[name=rate-c]:checked").value; st.t=0; st.pts=[[0,0]]; st.run=true; };
$("#rate-clear").onclick=()=>{ st.runs=[]; st.pts=[]; st.t=0; st.run=false; refresh(); draw(); };
$("#rate-tbody").addEventListener("click",e=>{ const b=e.target.closest(".x"); if(!b) return; st.runs.splice(+b.dataset.i,1); refresh(); });
const at=(r,t)=>(r.pts.find(p=>p[0]===t)||[0,0])[1];
function graph(){ const S=st.runs.map((r,i)=>({pts:r.pts,col:RUNCOL[i%6],join:"curve",label:`${r.c.toFixed(1)} mol/dm³`})); if(st.run) S.push({pts:st.pts,col:RUNCOL[st.runs.length%6],join:"curve",label:`${st.c.toFixed(1)} (running)`}); plot($("#rate-graph"),{x:{label:"Time / s",def:[0,120]},y:{label:"Volume of hydrogen / cm³",def:[0,100]},series:S,empty:"Start a run to plot the volume of gas"}); }
function refresh(){ rows($("#rate-tbody"),st.runs.map(r=>[r.c.toFixed(1),at(r,10),at(r,30),r.pts[r.pts.length-1][1],fx(at(r,30)/30,2)]),"Complete a run to record it.",5,true); graph(); work(); }
function work(){ const el=$("#rate-work"), {fr,res,step,chips}=W; if(!st.runs.length){ el.innerHTML=`<p class="empty">Complete a run and the calculation will appear here.</p>`; return; } const r=st.runs[st.runs.length-1], v=at(r,30);
  el.innerHTML=`<div class="work">`+step(1,"Mean rate over the first 30 s",`${r.c.toFixed(1)} mol/dm³ acid`,[`${fr(v+" cm³","30 s")} = ${res(fx(v/30,2)+" cm³/s")}`])+(st.runs.length>1?step(2,"Comparing runs",null,[`<span>${st.runs.slice().sort((a,b)=>a.c-b.c).map(x=>`${x.c.toFixed(1)} mol/dm³: ${fx(at(x,30)/30,2)} cm³/s`).join(" · ")}. Higher concentration gives a faster initial rate; the final volume is the same because the magnesium is limiting.</span>`]):"")+`</div>`; }
draw(); refresh();
register({id:"rate",group:"rp-chem",num:11,lvl:"RP 11",name:"Rates of reaction",icon:"rp-rate",onShow:()=>{draw();graph();}});
})();


/* RP12 Chromatography */
(()=>{
const {$,C,W,fx,gauss,bars,rows,build,register}=LAB;
const DY={E:[["yellow",.78,"#e3b81f"]],R:[["red",.52,"#d63a8a"]],B:[["blue",.30,"#3a7bd6"]],G:[["yellow",.78,"#e3b81f"],["blue",.30,"#3a7bd6"]],S:[["red",.52,"#d63a8a"],["blue",.30,"#3a7bd6"],["orange",.64,"#ef7d22"]]};
const LN=[["E","Yellow"],["R","Red"],["B","Blue"],["G","Green"],["S","Sweet coating"]];
const st={p:0,run:false,data:[]};
const F=230, Y0=380, X0=300;
const stage=`<svg id="chrom-svg" viewBox="0 0 900 470" role="img" aria-label="Chromatography paper in a beaker of water">${C.room()}<g id="chrom-g"></g></svg>`;
const panel=`<div class="btnrow"><button class="btn primary" id="chrom-go">Place paper in the solvent</button><button class="btn" id="chrom-re">New paper</button></div><div class="readout"><div><span>Solvent front</span><b id="chrom-sf">—</b></div><div><span>Status</span><b id="chrom-s">Ready</b></div></div><p class="note">When the solvent is near the top, the run stops. Click any spot to measure it with the ruler and record its R<sub>f</sub> value.</p>`;
build({id:"chrom",eyebrow:"AQA GCSE Combined Science · Chemistry · Required practical 12 · Chemical analysis",title:"Paper chromatography",
 intro:"Separate the food colourings in a sweet coating and identify them by comparing their R<sub>f</sub> values with those of known colourings.",
 stage,bar:`<span>Solvent: water</span><span>Ruler resolution 1 mm</span>`,panel,
 results:`<div class="tbl-wrap"><table><thead><tr><th>Sample</th><th>Spot</th><th>Distance moved by spot / cm</th><th>Solvent front / cm</th><th>R<sub>f</sub></th><th></th></tr></thead><tbody id="chrom-tbody"></tbody></table></div>`,
 graphTitle:"R<sub>f</sub> values",graphSub:"Matching R<sub>f</sub> = same substance",
 info:{method:["Draw a pencil line about 2 cm from the bottom of a piece of chromatography paper.","Put small, concentrated spots of each colouring on the line, well spaced, and label them in pencil.","Pour water into a beaker to a depth of about 1 cm (below the pencil line). Hang the paper so its bottom dips into the water. Cover with a lid.","When the solvent has nearly reached the top, remove the paper and mark the solvent front in pencil. Let it dry.","Measure the distance from the pencil line to the centre of each spot, and to the solvent front. Calculate R<sub>f</sub> = distance moved by spot ÷ distance moved by solvent."],
 vars:["(Analysis)","Distance moved by each spot / R<sub>f</sub>","Solvent, type of paper, temperature, starting line height"],
 safety:["Some solvents (not water) are flammable: no naked flames.","Wash hands after handling food colourings."],
 qa:[["Why is the start line drawn in pencil?","Graphite is insoluble, so it does not move with the solvent or mix with the spots."],["Why must the solvent be below the start line?","Otherwise the spots would dissolve into the solvent in the beaker."],["Why is a lid placed on the beaker?","To stop the solvent evaporating, so the paper stays saturated with vapour."],["Which colourings are in the sweet coating?","Red and blue (matching R<sub>f</sub> values), plus an orange dye not among the known samples."],["How could you show that the yellow colouring is a pure substance?","It gives a single spot in several different solvents."]]}});
function draw(){ const p=st.p, front=Y0-F*p; let g=GL.beaker(450,430,360,330,.11,"#9cc8e8",{op:.6})+`<rect x="250" y="70" width="400" height="${345}" fill="#fbfaf4" opacity=".97"/><rect x="230" y="64" width="440" height="8" fill="#888"/>`;
  g+=`<rect x="251" y="${Math.min(front,Y0)}" width="398" height="${Math.max(0,Y0+35-Math.min(front,Y0))}" fill="#9cc8e8" opacity=".25"/><path d="M255 ${Y0}h390" stroke="#666" stroke-width="1.2" stroke-dasharray="5 3"/>`;
  if(p>0) g+=`<path d="M255 ${front}h390" stroke="#2a6fd6" stroke-width="1" stroke-dasharray="2 3"/>`;
  LN.forEach(([k,n],i)=>{ const x=X0+i*75; g+=`<text x="${x}" y="${Y0+22}" text-anchor="middle" font-family="Arial" font-size="13" font-weight="700" fill="#222">${k}</text>`; DY[k].forEach(([dn,rf,col],j)=>{ g+=`<ellipse data-ch="${k}|${j}" cx="${x}" cy="${Y0-F*p*rf}" rx="9" ry="${6+p*3}" fill="${col}" style="cursor:pointer"/>`; }); });
  $("#chrom-g").innerHTML=g; $("#chrom-sf").textContent=p?`${fx(F*p/40,1)} cm`:"—"; $("#chrom-s").textContent=st.run?"Running":p>=1?"Finished: measure spots":"Ready"; }
CH.loop("chrom",dt=>{ if(!st.run) return; st.p=Math.min(1,st.p+dt/6); if(st.p>=1) st.run=false; draw(); });
$("#chrom-go").onclick=()=>{ if(st.p>=1) return; st.run=true; };
$("#chrom-re").onclick=()=>{ st.p=0; st.run=false; draw(); };
document.addEventListener("click",e=>{ const s=e.target.closest("[data-ch]"); if(!s) return; if(st.p<1){ $("#chrom-s").textContent="Wait until the run has finished"; return; } const [k,j]=s.dataset.ch.split("|"), d=DY[k][+j], sf=F/40, dist=Math.round((F*d[1]/40+gauss()*.03)*10)/10;
  st.data.push({k,col:d[0],d:dist,sf:+sf.toFixed(1)}); refresh(); });
$("#chrom-tbody").addEventListener("click",e=>{ const b=e.target.closest(".x"); if(!b) return; st.data.splice(+b.dataset.i,1); refresh(); });
function refresh(){ rows($("#chrom-tbody"),st.data.map(r=>[LN.find(x=>x[0]===r.k)[1],r.col,fx(r.d,1),fx(r.sf,1),fx(r.d/r.sf,2)]),"Click spots on the finished chromatogram to measure them.",5,true); graph(); work(); }
function graph(){ bars($("#chrom-graph"),{ylabel:"Rf",items:st.data.map(r=>({label:`${r.k} ${r.col}`,v:r.d/r.sf,vl:fx(r.d/r.sf,2),col:DY[r.k].find(x=>x[0]===r.col)[2]})),empty:"Measured Rf values will appear here"}); }
function work(){ const el=$("#chrom-work"), {fr,res,step}=W; if(!st.data.length){ el.innerHTML=`<p class="empty">Measure a spot and the calculation will appear here.</p>`; return; } const r=st.data[st.data.length-1];
  const S=st.data.filter(x=>x.k==="S"); el.innerHTML=`<div class="work">`+step(1,"R<sub>f</sub> of the last spot measured",`${LN.find(x=>x[0]===r.k)[1]}, ${r.col} spot`,[`R<sub>f</sub> = ${fr(fx(r.d,1)+" cm",fx(r.sf,1)+" cm")} = ${res(fx(r.d/r.sf,2))}`])+(S.length?step(2,"Identifying the sweet coating",null,[`<span>${S.map(x=>{ const m=st.data.find(y=>y.k!=="S"&&Math.abs(y.d/y.sf-x.d/x.sf)<0.03); return `${x.col} spot R<sub>f</sub> ${fx(x.d/x.sf,2)}: ${m?`matches ${LN.find(z=>z[0]===m.k)[1]}`:"no match among the known colourings measured"}`; }).join("; ")}.</span>`]):"")+`</div>`; }
draw(); refresh();
register({id:"chrom",group:"rp-chem",num:12,lvl:"RP 12",name:"Chromatography",icon:"rp-chrom",onShow:()=>{draw();graph();}});
})();


/* RP13 Water purification */
(()=>{
const {$,C,W,fx,gauss,bars,rows,build,register}=LAB;
const SM={tap:["Tap water",7.2,0.30],rain:["Rain water",5.6,0.03],river:["River water",7.6,0.60],sea:["Sea water",8.1,35.0],dist:["Distilled sea water",7.0,0.0]};
const st={k:"sea",basin:+(48+Math.random()*6).toFixed(2),stage:0,data:{},ph:null,mass:null};
const stage=`<svg id="water-svg" viewBox="0 0 900 470" role="img" aria-label="Analysing a water sample">${C.room()}${C.balance(620,300,"water-bal")}<g id="water-g"></g></svg>`;
const panel=`<div class="field"><div class="lbl">Sample</div><select id="water-s">${Object.entries(SM).map(([k,v])=>`<option value="${k}" ${k==="sea"?"selected":""}>${v[0]}</option>`).join("")}</select></div>
<div class="btnrow" style="flex-wrap:wrap"><button class="btn" id="water-ph">Measure pH</button><button class="btn" id="water-w0">Weigh empty basin</button><button class="btn" id="water-ev">Evaporate 50.0 cm³ to dryness</button><button class="btn" id="water-w1">Weigh basin again</button><button class="btn" id="water-dis">Distil the sea water</button></div>
<div class="readout"><div><span>pH</span><b id="water-p">—</b></div><div><span>Balance</span><b id="water-b">—</b></div></div><p class="note" id="water-h">Choose a sample, then test it.</p>`;
build({id:"water",eyebrow:"AQA GCSE Combined Science · Chemistry · Required practical 13 · Using resources",title:"Analysis and purification of water",
 intro:"Measure the pH and the mass of dissolved solids in water samples from different sources, then purify sea water by distillation and test the distillate.",
 stage,bar:`<span>Balance resolution 0.01 g</span><span>pH probe resolution 0.1</span>`,panel,
 results:`<div class="tbl-wrap"><table><thead><tr><th>Sample</th><th>pH</th><th>Basin / g</th><th>Basin + residue / g</th><th>Residue / g</th><th>Dissolved solids / g/dm³</th><th></th></tr></thead><tbody id="water-tbody"></tbody></table></div>`,
 graphTitle:"Dissolved solids",graphSub:"g per dm³ of water",
 info:{method:["Test the pH of each water sample with universal indicator paper or a pH probe.","Weigh a clean, dry evaporating basin.","Measure 50.0 cm³ of the sample into the basin and heat gently over a water bath until all the water has evaporated.","Let the basin cool and reweigh it. Calculate the mass of dissolved solids and the concentration in g/dm³.","Distil a sample of sea water: heat it in a flask, condense the steam in a Liebig condenser, and collect the distillate. Test the distillate's pH and dissolved solids."],
 vars:["Source of water","pH; mass of dissolved solids","Volume of sample; method of heating"],
 safety:["Wear eye protection; hot basins and glassware can burn.","Do not drink any samples.","Take care that the distillation flask does not boil dry; use anti-bumping granules."],
 qa:[["Why is the basin allowed to cool before reweighing?","A hot basin causes convection currents that make the balance reading inaccurate (and could damage the balance)."],["Why is sea water not potable?","It has a very high concentration of dissolved salts (about 35 g/dm³)."],["What results show that the distillate is pure water?","pH 7 and no residue on evaporation (boiling point 100 °C)."],["Why is rain water slightly acidic?","Carbon dioxide (and other gases) from the air dissolves in it."],["Why is distillation not used on a large scale in the UK?","It needs large amounts of energy, so it is expensive; fresh water is plentiful."]]}});
function draw(){ const s=SM[st.k]; let g="";
  if(st.stage===1) g+=GL.tripod(300,300,400,140)+GL.bunsen(300,400,true)+GL.basin(300,298,170,.4,"#9cc8e8");
  else if(st.stage===3) g+=`<circle cx="200" cy="300" r="50" fill="url(#g-glass)" stroke="#6f8a96"/><path d="M215 255l260 60v14l-260-60z" fill="url(#g-glass)" stroke="#6f8a96"/>`+GL.beaker(480,410,80,80,.3,"#dff0fa")+GL.bunsen(200,420,true)+`<text x="300" y="230" font-family="Arial" font-size="13" fill="#1d2a33">condenser</text>`;
  else g+=GL.beaker(300,410,140,120,.55,st.k==="sea"?"#8fbcd6":"#bcdbea")+(st.ph!=null?`<path d="M330 260v130" stroke="#333" stroke-width="6"/><rect x="310" y="210" width="80" height="44" rx="6" fill="#1d2a33"/><text x="350" y="240" text-anchor="middle" font-family="monospace" font-size="18" fill="#7ef0a0">${st.ph.toFixed(1)}</text>`:"");
  if(st.mass!=null) g+=GL.basin(710,320,90,0,"",st.stage>=2?"#f2f2ee":null);
  $("#water-g").innerHTML=g; $("#water-bal").textContent=st.mass!=null?fx(st.mass,2):"0.00"; $("#water-p").textContent=st.ph!=null?st.ph.toFixed(1):"—"; $("#water-b").textContent=st.mass!=null?`${fx(st.mass,2)} g`:"—"; }
const row=()=>st.data[st.k]=st.data[st.k]||{};
$("#water-s").onchange=()=>{ st.k=$("#water-s").value; st.stage=0; st.ph=null; st.mass=null; $("#water-h").textContent=st.k==="dist"&&!st.distilled?"Distil the sea water first.":"Test this sample."; draw(); };
$("#water-ph").onclick=()=>{ if(st.k==="dist"&&!st.distilled) return; st.ph=Math.round((SM[st.k][1]+gauss()*.05)*10)/10; row().ph=st.ph; refresh(); draw(); };
$("#water-w0").onclick=()=>{ if(st.k==="dist"&&!st.distilled) return; st.basin=+(48+Math.random()*6).toFixed(2); st.mass=st.basin; st.stage=0; row().b0=st.basin; delete row().b1; refresh(); draw(); };
$("#water-ev").onclick=()=>{ if(row().b0==null){ $("#water-h").textContent="Weigh the empty basin first."; return; } st.stage=1; draw(); setTimeout(()=>{ st.stage=2; $("#water-h").textContent="All the water has evaporated. Let it cool, then weigh."; draw(); },1200); };
$("#water-w1").onclick=()=>{ if(st.stage!==2) return; const m=+(row().b0+SM[st.k][2]*0.05+Math.max(0,gauss()*.004)).toFixed(2); st.mass=m; row().b1=m; refresh(); draw(); };
$("#water-dis").onclick=()=>{ if(st.k!=="sea"){ $("#water-h").textContent="Choose sea water to distil."; return; } st.stage=3; draw(); setTimeout(()=>{ st.distilled=true; $("#water-h").textContent="Distillate collected. Choose 'Distilled sea water' and test it."; },1500); };
$("#water-tbody").addEventListener("click",e=>{ const b=e.target.closest(".x"); if(!b) return; const k=Object.keys(st.data)[+b.dataset.i]; delete st.data[k]; refresh(); });
function refresh(){ const E=Object.entries(st.data); rows($("#water-tbody"),E.map(([k,r])=>[SM[k][0],r.ph!=null?r.ph.toFixed(1):"—",r.b0!=null?fx(r.b0,2):"—",r.b1!=null?fx(r.b1,2):"—",r.b1!=null?fx(r.b1-r.b0,2):"—",r.b1!=null?fx((r.b1-r.b0)/0.05,1):"—"]),"Test some samples to record results.",6,true); graph(); work(); }
function graph(){ bars($("#water-graph"),{ylabel:"Dissolved solids / g/dm³",items:Object.entries(st.data).filter(([k,r])=>r.b1!=null).map(([k,r])=>({label:SM[k][0],v:(r.b1-r.b0)/0.05,vl:fx((r.b1-r.b0)/0.05,1)})),empty:"Evaporate and weigh samples"}); }
function work(){ const el=$("#water-work"), {fr,res,step}=W; const E=Object.entries(st.data).filter(([k,r])=>r.b1!=null); if(!E.length){ el.innerHTML=`<p class="empty">Weigh a basin before and after evaporating a sample.</p>`; return; } const [k,r]=E[E.length-1], m=r.b1-r.b0;
  el.innerHTML=`<div class="work">`+step(1,"Mass of residue",SM[k][0],[`${fx(r.b1,2)} − ${fx(r.b0,2)} = ${fx(m,2)} g`])+step(2,"Concentration of dissolved solids","50.0 cm³ = 0.0500 dm³",[`${fr(fx(m,2)+" g","0.0500 dm³")} = ${res(fx(m/0.05,1)+" g/dm³")}`])+`</div>`; }
draw(); refresh();
register({id:"water",group:"rp-chem",num:13,lvl:"RP 13",name:"Water purification",icon:"rp-water",onShow:()=>{draw();graph();}});
})();


/* RP14 Specific heat capacity */
(()=>{
const {$,C,W,fmt,fx,sci,gauss,linfit,plot,rows,build,register,setThermo,setStopwatch,setPsu,store}=LAB;
const MAT={al:{name:"Aluminium",c:900,grad:"g-alu",top:"#d9dfe3",sw:"linear-gradient(90deg,#8e979e,#e9eef1,#7d868c)"},
           cu:{name:"Copper",c:385,grad:"g-copper",top:"#e7a07a",sw:"linear-gradient(90deg,#7a3a1c,#f0a77a,#6e3317)"},
           fe:{name:"Steel",c:450,grad:"g-steelBlk",top:"#9ba4ab",sw:"linear-gradient(90deg,#3f464c,#a8b1b8,#353b40)"}};
const RH=2.90, RI=0.18, M=1.00;
const st={mat:"al",V:12,lag:true,oil:true,dur:600,speed:30,stage:"ready",t:0,Tb:20,Th:20,Tth:20,Ta:20,next:0,data:[],runs:store.get("pl-shc-runs")||[],vr:0,ir:0};
st.Ta=20+Math.round(Math.random()*10)/10; st.Tb=st.Th=st.Tth=st.Ta;

/* ---------- scene ---------- */
const cx=520, topY=250, rx=62, ry=13, botY=362;
const magCx=812, magCy=118;
const stage=`<svg id="shc-svg" viewBox="0 0 900 470" role="img" aria-label="A metal block with an immersion heater and thermometer, connected to a power supply, ammeter and voltmeter, with a stopwatch">
<defs>
<pattern id="shc-lagp" width="16" height="16" patternUnits="userSpaceOnUse"><rect width="16" height="16" fill="#c9ccc8"/><path d="M0 8h16M8 0v16" stroke="#9fa39e" stroke-width=".8"/><circle cx="8" cy="8" r="1.1" fill="#8b8f8a"/><circle cx="0" cy="0" r="1.1" fill="#8b8f8a"/><circle cx="16" cy="16" r="1.1" fill="#8b8f8a"/><circle cx="16" cy="0" r="1.1" fill="#8b8f8a"/><circle cx="0" cy="16" r="1.1" fill="#8b8f8a"/></pattern>
<clipPath id="shc-thclip"><rect x="0" y="0" width="900" height="252"/></clipPath>
<clipPath id="shc-hclip"><rect x="0" y="0" width="900" height="250"/></clipPath>
</defs>
${C.room(306)}${C.benchFront(430)}
${C.mat(cx,384,230)}
${C.stand(640,392,16)}
${C.shadow(cx,botY+6,74,6)}
<g id="shc-block"></g>
<g clip-path="url(#shc-hclip)">
 <rect x="${cx-27}" y="200" width="14" height="60" fill="url(#g-steelV)"/>
</g>
<rect x="${cx-40}" y="190" width="40" height="13" rx="3" fill="#1f2326"/><rect x="${cx-40}" y="190" width="40" height="3" rx="1.5" fill="#4a5156"/>
<text x="${cx-20}" y="200" text-anchor="middle" font-family="Arial" font-size="4.6" fill="#9aa">12 V 50 W</text>
<rect x="${cx-35}" y="181" width="8" height="10" rx="2" fill="url(#g-termRed)"/><rect x="${cx-13}" y="181" width="8" height="10" rx="2" fill="url(#g-termBlack)"/>
<g id="shc-oil"></g>
<g clip-path="url(#shc-thclip)">${C.thermo(544,30,240,"shc-col",{scaleLen:200})}</g>
${C.clamp(640,80,544)}
${C.psu(14,268,"shc-psu")}
${C.lead("M512 184 C 520 100, 200 84, 174 338","black")}
${C.mm(214,214,"shc-am","A")}${C.mm(324,214,"shc-vm","V")}
${C.lead("M142 338 C 142 420, 236 430, 236 348","red")}
${C.lead("M264 348 C 270 440, 440 420, 446 300 S 472 176, 489 182","red")}
${C.lead("M402 348 C 404 420, 452 380, 455 292 S 478 190, 489 182","red")}
${C.lead("M374 348 C 372 446, 466 426, 463 300 S 500 178, 511 182","black")}
${C.plug(142,338,"red")}${C.plug(174,338,"black")}${C.plug(236,348,"red")}${C.plug(264,348,"black")}${C.plug(374,348,"black")}${C.plug(402,348,"red")}
<circle cx="489" cy="181" r="4.5" fill="#c62828"/><circle cx="511" cy="181" r="4.5" fill="#2a2a2a"/>
${C.stopwatch(742,284,"shc-sw")}
<line id="shc-lead" x1="${magCx-74}" y1="${magCy}" x2="546" y2="120" stroke="#e8823f" stroke-width="1.2" stroke-dasharray="4 3"/>
${C.mag(magCx,magCy,70,"shc-mag")}
</svg>`;

const panel=`
<div class="field"><div class="lbl">Metal block (1.00 kg)</div><div class="seg c3" id="shc-mats">${Object.entries(MAT).map(([k,m])=>`<label class="opt"><input type="radio" name="shc-mat" value="${k}" ${k===st.mat?"checked":""}><span>${m.name}</span></label>`).join("")}</div></div>
<div class="field"><div class="lbl">Power supply setting</div><div class="seg c4" id="shc-volts">${[6,8,10,12].map(v=>`<label class="opt"><input type="radio" name="shc-v" value="${v}" ${v===st.V?"checked":""}><span>${v} V</span></label>`).join("")}</div></div>
<label class="check"><input type="checkbox" id="shc-lag" checked> Insulating jacket round the block</label>
<label class="check"><input type="checkbox" id="shc-oiled" checked> Drop of oil in the thermometer hole</label>
<div class="row"><div class="field" style="flex:1"><div class="lbl">Total time</div><select id="shc-dur"><option value="600" selected>10 min</option><option value="900">15 min</option></select></div>
<div class="field" style="flex:1"><div class="lbl">Clock speed</div><select id="shc-speed"><option value="10">×10</option><option value="30" selected>×30</option><option value="60">×60</option></select></div></div>
<div class="readout c4" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div><span>Stopwatch</span><b id="shc-r-t">0 s</b></div><div><span>Temperature</span><b id="shc-r-T">—</b></div><div><span>Voltmeter</span><b id="shc-r-V">0.00 V</b></div><div><span>Ammeter</span><b id="shc-r-I">0.00 A</b></div></div>
<div class="field"><span class="step-tag" id="shc-step"></span><div class="btns"><button class="btn primary" id="shc-go">Switch on and start timing</button><button class="btn" id="shc-reset">Reset</button></div></div>`;

const sec=build({id:"shc",eyebrow:"AQA GCSE Combined Science · Physics · Required practical 14 · Energy",title:"Specific heat capacity",
 intro:"Heat a 1 kg metal block with an immersion heater. Record the temperature every minute, and use the voltmeter and ammeter readings to work out the energy transferred. The gradient of the temperature–energy graph gives the specific heat capacity.",
 stage,bar:`<span>Mass of block <b>1.00 kg</b></span><span>Room temperature <b id="shc-ta"></b></span><span>Heater <b>12 V, 50 W</b></span><span id="shc-status"></span>`,
 panel,
 results:`<div class="tbl-wrap"><table><thead><tr><th>Time / s</th><th>θ / °C</th><th>V / V</th><th>I / A</th><th>E = VIt / J</th></tr></thead><tbody id="shc-tbody"></tbody></table></div>
 <div class="tbl-wrap"><table><thead><tr><th>Run</th><th>c measured / J kg⁻¹ °C⁻¹</th><th>Accepted</th><th>Difference</th></tr></thead><tbody id="shc-runs"></tbody></table></div>`,
 resultsBtn:`<button class="btn" id="shc-clear" style="min-height:34px;padding:5px 10px">Clear runs</button>`,
 graphTitle:"Temperature against energy",graphSub:"Line of best fit through the straight part",
 info:{method:[
  "Measure and record the mass of the metal block (1.00 kg).",
  "Place the immersion heater in the larger hole and the thermometer in the smaller hole. Add a drop of oil to the thermometer hole so the bulb makes good thermal contact.",
  "Wrap the block in an insulating jacket to reduce energy transfer to the surroundings.",
  "Connect the heater to the power supply with an ammeter in series and a voltmeter in parallel across the heater.",
  "Record the starting temperature, then switch on the power supply and start the stopwatch.",
  "Record the temperature, voltmeter and ammeter readings every minute for 10 minutes.",
  "Calculate the energy transferred at each time using E = V × I × t, and plot temperature against energy.",
  "Draw a line of best fit through the straight part of the graph. Specific heat capacity = 1 ÷ (gradient × mass)."],
 vars:["Energy transferred to the block (time the heater is on)","Temperature of the block","Mass of the block, material of the block, power supply setting, insulation, starting temperature"],
 safety:["The heater and block get very hot. Do not touch them while switched on, and let them cool before packing away.","Place the block on a heat-proof mat.","Keep water away from the electrical equipment.","Use a low-voltage supply only, and switch off before changing connections."],
 qa:[["Why does the graph curve slightly at the start?","The heater has to warm up first, and the thermometer takes time to reach the block's temperature. Energy goes into the heater before it reaches the block, so the first readings rise slowly. Only the straight part is used to find the gradient."],
  ["Your value for the specific heat capacity is higher than the accepted value. Explain why.","Some energy from the heater is transferred to the surroundings and is not used to heat the block. So the measured energy is greater than the energy the block actually gains, which makes the calculated value of c too high."],
  ["How does the insulating jacket improve the experiment?","It reduces energy transfer from the block to the surroundings, so more of the energy supplied heats the block. The result is closer to the accepted value."],
  ["Why is a drop of oil put in the thermometer hole?","Air is a poor thermal conductor. Oil fills the gap and improves thermal contact, so the thermometer reading follows the block's temperature more closely."],
  ["Explain how the gradient of the graph gives the specific heat capacity.","From ΔE = m c Δθ, Δθ = (1 ÷ mc) × ΔE. So the gradient of θ against E is 1 ÷ (mc), and c = 1 ÷ (gradient × m)."],
  ["Suggest one way to improve the accuracy of the energy measurement.","Use a joulemeter connected to the heater to measure the energy transferred directly, rather than calculating it from separate meter readings."]]}
});

/* ---------- drawing ---------- */
function drawBlock(){
  const m=MAT[st.mat], L=st.lag;
  let s="";
  if(L){ const lx=rx+11; s+=`<path d="M${cx-lx} ${topY+6} V${botY+2} A${lx} ${ry+3} 0 0 0 ${cx+lx} ${botY+2} V${topY+6} A${lx} ${ry+3} 0 0 1 ${cx-lx} ${topY+6}Z" fill="url(#shc-lagp)" filter="url(#g-grain)"/>
   <path d="M${cx-lx} ${topY+6} V${botY+2} A${lx} ${ry+3} 0 0 0 ${cx+lx} ${botY+2} V${topY+6} A${lx} ${ry+3} 0 0 1 ${cx-lx} ${topY+6}Z" fill="url(#g-cyl)"/>
   <path d="M${cx-lx} ${topY+30} A${lx} ${ry+3} 0 0 0 ${cx+lx} ${topY+30} M${cx-lx} ${botY-30} A${lx} ${ry+3} 0 0 0 ${cx+lx} ${botY-30}" fill="none" stroke="#6f736e" stroke-width="1" stroke-dasharray="3 2"/>`; }
  s+=`<path d="M${cx-rx} ${topY} V${botY} A${rx} ${ry} 0 0 0 ${cx+rx} ${botY} V${topY}Z" fill="url(#${m.grad})" opacity="${L?0:1}"/>`;
  if(!L) s+=`<path d="M${cx-rx} ${topY} V${botY} A${rx} ${ry} 0 0 0 ${cx+rx} ${botY} V${topY}Z" fill="url(#g-cyl)" opacity=".5"/><text x="${cx}" y="${botY-14}" text-anchor="middle" font-family="Arial" font-size="9" font-weight="bold" fill="#000" opacity=".28">1 kg</text>`;
  s+=`<ellipse cx="${cx}" cy="${topY}" rx="${rx}" ry="${ry}" fill="${m.top}"/><ellipse cx="${cx}" cy="${topY}" rx="${rx}" ry="${ry}" fill="url(#${m.grad})" opacity=".55"/><ellipse cx="${cx}" cy="${topY}" rx="${rx-1}" ry="${ry-1}" fill="none" stroke="#fff" stroke-opacity=".35"/>
  <ellipse cx="${cx-20}" cy="${topY}" rx="10" ry="3.4" fill="#16191b"/><ellipse cx="${cx+24}" cy="${topY+2}" rx="5.5" ry="2" fill="#16191b"/>`;
  $("#shc-block").innerHTML=s;
  $("#shc-oil").innerHTML=st.oil?`<ellipse cx="${cx+24}" cy="${topY+2}" rx="7.5" ry="2.8" fill="#c99a2e" opacity=".55"/><ellipse cx="${cx+22}" cy="${topY+1}" rx="2" ry=".8" fill="#fff" opacity=".7"/>`:"";
}
(function magScale(){
  let m=`<rect x="${magCx-44}" y="-1220" width="88" height="1440" fill="url(#g-thGlass)"/><rect x="${magCx-20}" y="-1220" width="64" height="1440" fill="#f6f3e8"/><rect x="${magCx-31}" y="-1220" width="10" height="1440" fill="#ffffff" opacity=".55"/>`;
  m+=`<rect id="shc-magcol" x="${magCx-29}" y="0" width="6" height="1500" fill="url(#g-red)"/>`;
  for(let T=-10;T<=110;T++){ const y=-T*10, L=T%10===0?22:T%5===0?15:8;
    m+=`<line x1="${magCx-20}" x2="${magCx-20+L}" y1="${y}" y2="${y}" stroke="#151515" stroke-width="${T%5===0?1.4:1}"/>`;
    if(T%5===0) m+=`<text x="${T%10===0?magCx+6:magCx-2}" y="${y+4.5}" font-size="${T%10===0?14:11}" font-family="'JetBrains Mono',monospace" font-weight="${T%10===0?600:400}" fill="#151515">${T}</text>`; }
  m+=`<line x1="${magCx-74}" y1="0" x2="${magCx+74}" y2="0" stroke="#c4531a" stroke-width="1.2" stroke-dasharray="5 4" opacity=".9" transform="translate(0 0)" id="shc-magline"/>`;
  $("#shc-mag").innerHTML=m;
})();
function render(){
  const T=st.Tth;
  const y=setThermo("shc-col",T);
  $("#shc-mag").setAttribute("transform",`translate(0 ${(magCy+T*10).toFixed(2)})`);
  $("#shc-magcol").setAttribute("y",(-T*10).toFixed(2));
  $("#shc-magline").setAttribute("y1",-T*10); $("#shc-magline").setAttribute("y2",-T*10);
  $("#shc-lead").setAttribute("y2",y.toFixed(1));
  setStopwatch($("#shc-sw"),st.t);
  const on=st.stage==="running";
  $("#shc-am").textContent=on?fx(st.ir,2):"0.00"; $("#shc-vm").textContent=on?fx(st.vr,2):"0.00";
  setPsu("shc-psu",st.V,12,on);
  $("#shc-r-t").textContent=`${Math.floor(st.t)} s`; $("#shc-r-T").textContent=`${(Math.round(T*2)/2).toFixed(1)} °C`;
  $("#shc-r-V").textContent=`${on?fx(st.vr,2):"0.00"} V`; $("#shc-r-I").textContent=`${on?fx(st.ir,2):"0.00"} A`;
}

/* ---------- physics ---------- */
function elec(){ const I=st.V/(RH+RI); return {I,V:I*RH}; }
function step(dt){
  const on=st.stage==="running", k=st.lag?0.07:0.30, P=on?(()=>{const e=elec();return e.V*e.I;})():0;
  const Ch=55, G=5.5, mc=M*MAT[st.mat].c, tau=st.oil?5:40;
  let n=Math.max(1,Math.ceil(dt/0.5)), h=dt/n;
  for(let i=0;i<n;i++){
    const q=G*(st.Th-st.Tb);
    st.Th+=h*(P-q-0.02*(st.Th-st.Ta))/Ch;
    st.Tb+=h*(q-k*(st.Tb-st.Ta))/mc;
    st.Tth+=(st.Tb-st.Tth)*(1-Math.exp(-h/tau));
  }
}
function takeReading(t){
  const T=Math.round((st.Tth+gauss()*.08)*2)/2;
  st.data.push({t,T,V:+fx(st.vr,2),I:+fx(st.ir,2)});
}
const STEPS={ready:"Step 1 of 2 · set up, then switch on",running:"Step 2 of 2 · a reading is taken every minute",done:"Run complete · the calculation is below"};
function setStage(s){ st.stage=s; $("#shc-step").textContent=STEPS[s];
  $("#shc-go").textContent=s==="ready"?"Switch on and start timing":s==="running"?"Switch off early":"Cool the block and start again";
  const lock=s!=="ready"; document.querySelectorAll('[name="shc-mat"],[name="shc-v"],#shc-lag,#shc-oiled,#shc-dur').forEach(i=>i.disabled=lock);
  $("#shc-status").textContent=s==="ready"?"Heater off. Block at room temperature.":s==="running"?"Heater on. Readings every 60 s.":"Heater off. Data recorded.";
}
function finish(){
  setStage("done");
  const r=analyse(); if(r){ st.runs.push({label:`${MAT[st.mat].name}, ${st.V} V${st.lag?"":", no jacket"}${st.oil?"":", no oil"}`,c:r.c,acc:MAT[st.mat].c}); if(st.runs.length>6) st.runs.shift(); store.set("pl-shc-runs",st.runs); }
  refresh();
}
let last=performance.now();
function loop(now){
  const dt=Math.min(.1,(now-last)/1000); last=now;
  if(st.stage==="running"){
    const e=elec(); st.vr=e.V+gauss()*.008; st.ir=e.I+gauss()*.006;
    let sim=dt*st.speed;
    while(sim>0){ const to=Math.min(sim,st.next-st.t); if(to>0){ step(to); st.t+=to; sim-=to; }
      if(st.t>=st.next-1e-9){ takeReading(st.next); st.next+=60; refresh(); if(st.t>=st.dur-1e-9){ finish(); break; } } }
  } else step(dt*(st.stage==="done"?1:1));
  render(); requestAnimationFrame(loop);
}

/* ---------- analysis ---------- */
function analyse(){
  const d=st.data; if(d.length<3) return null;
  const pts=d.map(r=>[r.V*r.I*r.t,r.T]);
  let use=d.map((r,i)=>r.t>=120); if(use.filter(Boolean).length<3) use=d.map(()=>true);
  const fp=pts.filter((p,i)=>use[i]); const f=linfit(fp); if(!f||f.m<=0) return null;
  const [xa,xb]=LAB.triX(fp.map(p=>p[0]));
  return {pts,use,f,xa,xb,c:1/(f.m*M)};
}
function refresh(){
  rows($("#shc-tbody"),st.data.map(r=>[r.t,fx(r.T,1),fx(r.V,2),fx(r.I,2),Math.round(r.V*r.I*r.t).toLocaleString("en-GB")]),"Switch on to start taking readings.",5);
  rows($("#shc-runs"),st.runs.map(r=>[r.label,Math.round(r.c).toLocaleString("en-GB"),r.acc,`${r.c>r.acc?"+":""}${fx((r.c-r.acc)/r.acc*100,0)}%`]),"Completed runs are compared here.",4);
  draw(); work();
}
function draw(){
  const a=analyse(), pts=st.data.map(r=>[r.V*r.I*r.t,r.T]);
  const o={x:{label:"Energy transferred E / J",def:[0,30000]},y:{label:"Temperature θ / °C",zero:false,def:[15,50]},series:[{pts,col:LAB.RUNCOL[0],mark:a?a.use.map(u=>!u):null}],empty:"Readings will be plotted here as they are taken"};
  if(a){ o.fits=[{m:a.f.m,c:a.f.c,x0:0,x1:Math.max(...pts.map(p=>p[0])),col:LAB.css("--ink"),dash:[],label:"line of best fit"}];
    o.tri={m:a.f.m,c:a.f.c,xa:a.xa,xb:a.xb,dxl:"ΔE",dyl:"Δθ"}; o.legend="left"; }
  plot($("#shc-graph"),o);
}
function work(){
  const a=analyse(), el=$("#shc-work"); if(!a){ el.innerHTML=`<p class="empty">Take at least three readings and the calculation will appear here.</p>`; return; }
  const {v,fr,res,step,chips}=W, d=st.data, last=d[d.length-1];
  const Vm=d.reduce((s,r)=>s+r.V,0)/d.length, Im=d.reduce((s,r)=>s+r.I,0)/d.length, P=Vm*Im;
  const ya=a.f.m*a.xa+a.f.c, yb=a.f.m*a.xb+a.f.c, acc=MAT[st.mat].c, pc=(a.c-acc)/acc*100;
  el.innerHTML=chips([["Power",`${fmt(P)} W`],["Gradient",`${sci(a.f.m,3)} °C/J`],["c measured",`${Math.round(a.c)} J/kg°C`,1],["Accepted",`${acc} J/kg°C`]])+
  `<div class="work" style="margin-top:14px">`+
  step(1,"Power of the heater","Use the mean meter readings.",[`${v("P")} = ${v("V")}${v("I")} = ${fx(Vm,2)} × ${fx(Im,2)} = ${res(`${fmt(P)} W`)}`])+
  step(2,"Energy transferred at each reading",`Energy = power × time. For the last reading, at t = ${last.t} s:`,[`${v("E")} = ${v("V")}${v("I")}${v("t")} = ${fx(last.V,2)} × ${fx(last.I,2)} × ${last.t} = ${res(`${Math.round(last.V*last.I*last.t).toLocaleString("en-GB")} J`)}`])+
  step(3,"Gradient of the straight part","Ignore the first readings while the heater warms up. Use two points far apart on the line of best fit.",[`gradient = ${fr("Δθ","Δ"+v("E"))} = ${fr(`${fx(yb,1)} − ${fx(ya,1)}`,`${Math.round(a.xb)} − ${Math.round(a.xa)}`)} = ${res(`${sci(a.f.m,4)} °C/J`)}`])+
  step(4,"Specific heat capacity",`Since Δ${v("E")} = ${v("m")}${v("c")}Δθ, the gradient Δθ/Δ${v("E")} = 1/(${v("m")}${v("c")}).`,[`${v("c")} = ${fr("1",`gradient × ${v("m")}`)} = ${fr("1",`${sci(a.f.m,4)} × ${fx(M,2)}`)} = ${res(`${Math.round(a.c)} J/kg °C`)}`])+
  step(5,"Compare with the accepted value",`Accepted value for ${MAT[st.mat].name.toLowerCase()}: ${acc} J/kg °C.`,[`percentage difference = ${fr(`${Math.round(a.c)} − ${acc}`,acc)} × 100 = ${res(`${pc>0?"+":""}${fx(pc,1)}%`)}`,
    `<span class="muted">${pc>3?"Higher than accepted: some energy was transferred to the surroundings instead of heating the block.":pc<-3?"Lower than accepted: check the readings for anomalies.":"Very close to the accepted value."}</span>`])+`</div>`;
}

/* ---------- controls ---------- */
$("#shc-mats").addEventListener("change",e=>{st.mat=e.target.value; drawBlock();});
$("#shc-volts").addEventListener("change",e=>{st.V=+e.target.value; render();});
$("#shc-lag").addEventListener("change",e=>{st.lag=e.target.checked; drawBlock();});
$("#shc-oiled").addEventListener("change",e=>{st.oil=e.target.checked; drawBlock();});
$("#shc-dur").addEventListener("change",e=>st.dur=+e.target.value);
$("#shc-speed").addEventListener("change",e=>st.speed=+e.target.value);
function reset(){ st.Ta=20+Math.round(Math.random()*10)/10; st.Tb=st.Th=st.Tth=st.Ta; st.t=0; st.data=[]; st.vr=st.ir=0; $("#shc-ta").textContent=`${fx(st.Ta,1)} °C`; setStage("ready"); refresh(); }
$("#shc-go").addEventListener("click",()=>{
  if(st.stage==="ready"){ st.t=0; st.next=0; st.data=[]; const e=elec(); st.vr=e.V; st.ir=e.I; setStage("running"); takeReading(0); st.next=60; refresh(); }
  else if(st.stage==="running"){ finish(); }
  else reset();
});
$("#shc-reset").addEventListener("click",reset);
$("#shc-clear").addEventListener("click",()=>{st.runs=[]; store.set("pl-shc-runs",[]); refresh();});

drawBlock(); reset(); render(); requestAnimationFrame(loop);
register({id:"shc",group:"rp-phys",num:14,lvl:"RP 14",name:"Specific heat capacity",icon:"shc",onShow:draw});
})();



